encode <- function(s, running, zero) {
    for (track in s$tracks) {
        row <- numeric()
        last <- 0
        status <- 0
        for (e in track) {
            row <- c(row, vlq(e$tick - last))
            last <- e$tick
            st <- e$status
            body <- e$data
            if (zero && st %/% 16 == 8) {
                st <- st + 16
                body <- c(body[1], 0)
            }
